import httpx


def make_proxied_client(proxy_url: str, base_url: str) -> httpx.Client:
    """Create an httpx.Client for base_url whose requests go through the HTTP proxy proxy_url,
    with 5-second timeout and User-Agent header 'inventory-sync/1.0'."""
    headers = {"User-Agent": "inventory-sync/1.0"}
    timeout = 5.0
    # httpx 0.28 removed proxies= argument, so use transport with ProxyTransport
    transport = httpx.ProxyTransport(proxy_url)
    return httpx.Client(base_url=base_url, headers=headers, timeout=timeout, transport=transport)

